"""Campaign compiler, typed replay, filtering, and state preparation.

The pipeline compiles typed model layouts into per-entry plans, recovers
recorded symbolic tests strictly against those layouts, validates scoped
predicates with exact arithmetic, attests pipe flags, prepares deterministic
state preambles and finally assigns corpus identity.
"""

import sys

from .ast import (Bool, Const, Expr, ExpressionError, Int, String, Struct,
                  Type, build_types, compile_expression, values_equal)
from .composer import Application, DependencyError, DependencyGraph, compose
from .oracles import (BOOL_SPEC, LayoutBuilder, TestError, ValueReader,
                      declaration_postorder, walk_type)
from .regex import RegexError
from .run import freeze, identity
from .state import StateMachine
from .wire import TransportError, decode_ktest

_UNSET = object()
_GUARD_CACHE_LIMIT = 100000
_PATTERN_CACHE_LIMIT = 100000


class InvalidInput(Exception):
    """Raised when the campaign itself is outside the documented domain."""


class Module(object):
    """A compiled model module."""

    __slots__ = ('name', 'params', 'param_types', 'result', 'requires_source',
                 'requirement', 'pipes', '_applications', '_scope',
                 '_requirement_ready')

    def __init__(self, spec, types):
        self.name = spec['name']
        self.params = [(parameter, types[type_name])
                       for parameter, type_name in spec['params']]
        self.param_types = dict(self.params)
        result = spec.get('result')
        if result is None:
            self.result = None
        else:
            self.result = (result[0], types[result[1]])
        self.requires_source = spec.get('requires')
        self.requirement = None
        self._requirement_ready = False
        self.pipes = []
        self._applications = None
        self._scope = None

    def scope(self):
        if self._scope is None:
            self._scope = {name: Type.inner(kind)
                           for name, kind in self.param_types.items()}
        return self._scope

    def requirement_expr(self, compile_predicate):
        if not self._requirement_ready:
            self._requirement_ready = True
            if self.requires_source is not None:
                self.requirement = compile_predicate(self.requires_source,
                                                     self.scope())
        return self.requirement

    def applications(self):
        if self._applications is None:
            self._applications = compose(self, lambda module: module.pipes)
        return self._applications

    def own_result(self):
        """Result type without the void case, or ``None`` for void."""
        if self.result is None:
            return None
        if isinstance(Type.inner(self.result[1]), Bool):
            pass
        return self.result


class Pipe(object):
    """A pipe binding a filter's parameters onto its target's parameters."""

    __slots__ = ('target', 'filter', 'bind')

    def __init__(self, spec, modules):
        self.target = spec['target']
        self.filter = modules[spec['filter']]
        self.bind = dict(spec['bind'])


class Plan(object):
    """One compiled entry plan and its symbolic inventory."""

    __slots__ = ('entry', 'module', 'modules', 'types', 'slots', 'flag',
                 'variables', 'inventory', 'param_types', 'param_order',
                 'result_name', 'result_type')

    def __init__(self, entry, module, modules, types, slots, flag, variables,
                 inventory):
        self.entry = entry
        self.module = module
        self.modules = modules
        self.types = types
        self.slots = slots
        self.flag = flag
        self.variables = variables
        self.inventory = inventory
        self.param_types = module.param_types
        self.param_order = [name for name, _ in module.params]
        if module.result is None:
            self.result_name = None
            self.result_type = None
        else:
            self.result_name = module.result[0]
            if isinstance(Type.inner(module.result[1]), Type) and \
                    isinstance(Type.inner(module.result[1]), Void().__class__):
                self.result_type = None
            else:
                self.result_type = module.result[1]

    def to_json(self):
        return {
            'entry': self.entry,
            'modules': self.modules,
            'types': self.types,
            'slots': self.slots,
            'flag': self.flag,
            'variables': self.variables,
        }


class Campaign(object):
    """A compiled offline campaign."""

    def __init__(self, request):
        if not isinstance(request, dict):
            raise InvalidInput('campaign root must be an object')
        self.types = build_types(request.get('types') or [])
        self.modules = {}
        for spec in (request.get('modules') or []):
            name = spec['name']
            if name in self.modules:
                raise InvalidInput('duplicate module ' + str(name))
            self.modules[name] = Module(spec, self.types)
        self.graph = DependencyGraph()
        for name in self.modules:
            self.graph.add_node(name)
        for pair in (request.get('calls') or []):
            caller, callee = pair[0], pair[1]
            self.graph.add_edge(caller, callee)
        pipes = []
        for spec in (request.get('pipes') or []):
            pipes.append(Pipe(spec, self.modules))
        for pipe in pipes:
            self.graph.add_edge(pipe.target, pipe.filter)
        for pipe in pipes:
            self.modules[pipe.target].pipes.append(pipe)
        self.entries = list(request.get('entries') or [])
        self.runs = list(request.get('runs') or [])
        machine = request.get('machine')
        self.machine = None if machine is None else StateMachine(machine, freeze)
        self.patterns = {}
        self._guards = {}
        self.corpus = []
        self._cases = {}
        self.plans = []
        self._plans_by_entry = {}

    # -- compilation ----------------------------------------------------
    def compile_predicate(self, source, scope):
        if source is None:
            return None
        return compile_expression(source, scope, self.types, self.patterns)

    def build_plan(self, name):
        module = self.modules[name]
        order = self.graph.compile_order(name)
        declarations = []
        seen = set()
        for module_name in order:
            other = self.modules[module_name]
            for _, parameter_type in other.params:
                declaration_postorder(parameter_type, declarations, seen)
            if other.result is not None:
                declaration_postorder(other.result[1], declarations, seen)
        layout = LayoutBuilder()
        for parameter, parameter_type in module.params:
            walk_type(parameter_type, [parameter], layout)
        plan = Plan(name, module, order, declarations, layout.slots, None,
                    layout.number, layout.inventory)
        if module.result is not None and plan.result_type is not None:
            walk_type(plan.result_type, [plan.result_name], layout)
        if module.pipes:
            plan.flag = layout.reserve_flag()
        plan.variables = layout.number
        return plan

    # -- recovery -------------------------------------------------------
    def recover(self, plan, objects):
        reader = ValueReader(objects)
        values = {}
        for parameter, parameter_type in plan.module.params:
            values[parameter] = walk_type(parameter_type, [parameter], reader)
        model_result = None
        if plan.result_type is not None:
            model_result = walk_type(plan.result_type, [plan.result_name],
                                     reader)
        return values, model_result

    # -- records --------------------------------------------------------
    def record(self, position, run):
        entry = run.get('entry') if isinstance(run, dict) else None
        plan = self._plans_by_entry.get(entry)
        if plan is None:
            return {'status': 'INVALID_TEST'}
        try:
            objects = decode_ktest(run.get('ktest'))
            values, model_result = self.recover(plan, objects)
        except (TransportError, TestError):
            return {'status': 'INVALID_TEST'}
        module = plan.module
        accepted = True
        for application in module.applications():
            if not application.accepts(values, Expr.eval):
                accepted = False
                break
        if plan.flag is not None:
            data = objects.get(plan.flag)
            if data is None:
                return {'status': 'INVALID_TEST'}
            try:
                attested = plan.inventory[plan.flag].read(data)
            except TestError:
                return {'status': 'INVALID_TEST'}
            if attested != (not accepted):
                return {'status': 'INVALID_TEST'}
        requirement = module.requirement_expr(self.compile_predicate)
        if requirement is not None and not Expr.eval(requirement, values):
            return {'status': 'FILTERED'}
        if not accepted:
            return {'status': 'FILTERED'}
        cost, commands = self._preparation(entry, values)
        if cost is None:
            return {'status': 'UNREACHABLE'}
        key = identity(entry, values)
        case = self._cases.get(key)
        if case is None:
            case = len(self.corpus)
            self._cases[key] = case
            self.corpus.append({
                'entry': entry,
                'inputs': values,
                'cost': cost,
                'commands': commands,
                'witnesses': [position],
            })
            return {'status': 'READY', 'case': case,
                    'model_result': model_result}
        self.corpus[case]['witnesses'].append(position)
        return {'status': 'DUPLICATE', 'case': case,
                'model_result': model_result}

    def _preparation(self, entry, values):
        machine = self.machine
        if machine is None:
            return 0, []
        target = machine.index.get(values.get(machine.state_param))
        if target is None:
            raise InvalidInput('recovered state is not a machine state')
        enabled = self._enabled_guards(entry, machine, values)
        prepared = machine.plan(target, enabled)
        if prepared is None:
            return None, None
        cost, commands = prepared
        commands = list(commands)
        commands.append(values[machine.message_param])
        return cost, commands

    def _enabled_guards(self, entry, machine, values):
        scope = self.modules[entry].scope()
        cache = self._guards
        enabled = []
        for position, key in enumerate(machine.guard_keys):
            if key is None:
                enabled.append(True)
                continue
            token = (entry, key)
            guard = cache.get(token)
            if guard is None:
                guard = self.compile_predicate(machine.guard_sources[position],
                                               scope)
                if len(cache) >= _GUARD_CACHE_LIMIT:
                    cache.clear()
                cache[token] = guard
            enabled.append(bool(Expr.eval(guard, values)))
        return enabled

    # -- certificate ----------------------------------------------------
    def certificate(self):
        plans = []
        for entry in self.entries:
            plan = self.build_plan(entry)
            self.plans.append(plan)
            self._plans_by_entry[entry] = plan
        records = []
        for position, run in enumerate(self.runs):
            records.append(self.record(position, run))
        return {
            'plans': [plan.to_json() for plan in self.plans],
            'records': records,
            'corpus': self.corpus,
        }


def _execute(request):
    return Campaign(request).certificate()


def execute(campaign):
    """Run the offline pipeline; the JSON certificate is the interface."""
    try:
        return _execute(campaign)
    except (InvalidInput, ExpressionError, RegexError, DependencyError,
            TestError, KeyError, TypeError, ValueError, IndexError,
            AttributeError, RecursionError) as failure:
        sys.stderr.write('eywa: %s: %s\n' % (failure.__class__.__name__, failure))
        return {'error': 'INVALID_INPUT'}
    except Exception as failure:  # pragma: no cover - defensive
        sys.stderr.write('eywa: unexpected %s: %s\n'
                         % (failure.__class__.__name__, failure))
        return {'error': 'INVALID_INPUT'}
